import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 全册易错点 · 第23–45课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第四册：流利英语 · 全册易错点 · 第23–45课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-4/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册易错点 · 第1–22课","link":"/life/english/new-concept/book-4/mistakes-part-01"},"next":{"text":"第四册：流利英语 · 全册易错点 · 第46–48课","link":"/life/english/new-concept/book-4/mistakes-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册易错点 · 第1–22课","link":"/life/english/new-concept/book-4/mistakes-part-01"},"next":{"text":"第四册：流利英语 · 全册易错点 · 第46–48课","link":"/life/english/new-concept/book-4/mistakes-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-4/mistakes-part-02.md","filePath":"life/english/new-concept/book-4/mistakes-part-02.md"}'),r={name:"life/english/new-concept/book-4/mistakes-part-02.md"};function i(s,e,l,h,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-全册易错点-·-第23–45课" tabindex="-1">第四册：流利英语 · 全册易错点 · 第23–45课 <a class="header-anchor" href="#第四册-流利英语-·-全册易错点-·-第23–45课" aria-label="Permalink to &quot;第四册：流利英语 · 全册易错点 · 第23–45课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="l23-·-现在分词状语与逻辑主语" tabindex="-1">L23 · 现在分词状语与逻辑主语 <a class="header-anchor" href="#l23-·-现在分词状语与逻辑主语" aria-label="Permalink to &quot;L23 · 现在分词状语与逻辑主语 {#l23-·-现在分词状语与逻辑主语}&quot;">​</a></h2><p>Watching the bird, its wings looked wide 错把 wings 当观察者；可改为 As I watched the bird, its wings looked wide。</p><p><strong>对照例句：</strong> Gliding above the field, the bird turned towards the hills.</p><p>Gliding… 为伴随分词状语，逻辑主语为 the bird，与 turned 的主语一致。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">回看讲解和练习</a></p><h2 id="l24-·-否定或限制副词前置倒装" tabindex="-1">L24 · 否定或限制副词前置倒装 <a class="header-anchor" href="#l24-·-否定或限制副词前置倒装" aria-label="Permalink to &quot;L24 · 否定或限制副词前置倒装 {#l24-·-否定或限制副词前置倒装}&quot;">​</a></h2><p>Rarely two viewers notice… 缺倒装；Rarely do two viewers notices… 又错误地给实义动词加 s。</p><p><strong>对照例句：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><p>Rarely 前置触发 do two viewers 的部分倒装；notice 保持原形；不是把整句完全颠倒。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">回看讲解和练习</a></p><h2 id="l25-·-名词化与施事信息" tabindex="-1">L25 · 名词化与施事信息 <a class="header-anchor" href="#l25-·-名词化与施事信息" aria-label="Permalink to &quot;L25 · 名词化与施事信息 {#l25-·-名词化与施事信息}&quot;">​</a></h2><p>exposure of noise 应改 exposure to noise；coincided with 也不能自动替换为 caused。</p><p><strong>对照例句：</strong> A reduction in background noise coincided with fewer interruptions during the task.</p><p>A reduction… 是名词化主语；coincided with 只说明同时发生，没有直接宣称因果。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">回看讲解和练习</a></p><h2 id="l26-·-完成式分词状语" tabindex="-1">L26 · 完成式分词状语 <a class="header-anchor" href="#l26-·-完成式分词状语" aria-label="Permalink to &quot;L26 · 完成式分词状语 {#l26-·-完成式分词状语}&quot;">​</a></h2><p>Having compared the layers, a sequence was proposed 容易让 sequence 成为比较者；应明确主语 researchers。</p><p><strong>对照例句：</strong> Having compared the layers, the researchers proposed a tentative sequence of events.</p><p>Having compared 表先行完成动作；researchers 同时是 compare 和 propose 的执行者；tentative 限定结论。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">回看讲解和练习</a></p><h2 id="l27-·-第三条件句与过去反事实" tabindex="-1">L27 · 第三条件句与过去反事实 <a class="header-anchor" href="#l27-·-第三条件句与过去反事实" aria-label="Permalink to &quot;L27 · 第三条件句与过去反事实 {#l27-·-第三条件句与过去反事实}&quot;">​</a></h2><p>If the model would have been tested 错把结果形式放入条件；应写 had been tested。</p><p><strong>对照例句：</strong> If the model had been tested earlier, the designers might have noticed the imbalance.</p><p>had been tested 是过去完成时被动条件；might have noticed 表对过去替代结果的谨慎推测。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">回看讲解和练习</a></p><h2 id="l28-·-间接问句与疑问语序" tabindex="-1">L28 · 间接问句与疑问语序 <a class="header-anchor" href="#l28-·-间接问句与疑问语序" aria-label="Permalink to &quot;L28 · 间接问句与疑问语序 {#l28-·-间接问句与疑问语序}&quot;">​</a></h2><p>Could you explain what does this term mean? 错用直接问句语序；应去 does 并用 means。</p><p><strong>对照例句：</strong> Could you explain what this term means in plain language?</p><p>Could you explain 是礼貌主句；what this term means 为宾语从句，this term 在 means 前。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">回看讲解和练习</a></p><h2 id="l29-·-使役与许可结构" tabindex="-1">L29 · 使役与许可结构 <a class="header-anchor" href="#l29-·-使役与许可结构" aria-label="Permalink to &quot;L29 · 使役与许可结构 {#l29-·-使役与许可结构}&quot;">​</a></h2><p>allows the model move 缺少 to；不要把 allow 的结构误套成 make 的结构。</p><p><strong>对照例句：</strong> The air cushion allows the model to move across the smooth floor.</p><p>allows + the model + to move 是宾语加不定式补足语；air cushion 为提供条件的主语。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">回看讲解和练习</a></p><h2 id="l30-·-介词-which-的关系从句" tabindex="-1">L30 · 介词 + which 的关系从句 <a class="header-anchor" href="#l30-·-介词-which-的关系从句" aria-label="Permalink to &quot;L30 · 介词 + which 的关系从句 {#l30-·-介词-which-的关系从句}&quot;">​</a></h2><p>under that the sensor operates 不成立；介词前置的关系结构用 which。</p><p><strong>对照例句：</strong> The pressure under which the sensor operates must be recorded.</p><p>under which 修饰 pressure；主句主语是整个名词短语，must be recorded 为谓语。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">回看讲解和练习</a></p><h2 id="l31-·-独立主格的主语与分词" tabindex="-1">L31 · 独立主格的主语与分词 <a class="header-anchor" href="#l31-·-独立主格的主语与分词" aria-label="Permalink to &quot;L31 · 独立主格的主语与分词 {#l31-·-独立主格的主语与分词}&quot;">​</a></h2><p>不要把独立主格误写成 The clay was still damp, the sculptor covered…；两个完整句不能仅用逗号连接。</p><p><strong>对照例句：</strong> The clay still damp, the sculptor covered the model before leaving.</p><p>The clay still damp 有自己的主语 clay 和形容词 damp，补充背景；主句主语是 sculptor。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">回看讲解和练习</a></p><h2 id="l32-·-形容词前置的-as-让步结构" tabindex="-1">L32 · 形容词前置的 as 让步结构 <a class="header-anchor" href="#l32-·-形容词前置的-as-让步结构" aria-label="Permalink to &quot;L32 · 形容词前置的 as 让步结构 {#l32-·-形容词前置的-as-让步结构}&quot;">​</a></h2><p>As the evidence is limited 通常更容易读成“因为证据有限”；要保留让步意思可用 Although 或前置 Limited as。</p><p><strong>对照例句：</strong> Limited as the evidence is, it gives us a reason to repeat the experiment.</p><p>Limited 前置，as 引导让步；it 指 evidence；主句主张重复检验而不是立即接受结论。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">回看讲解和练习</a></p><h2 id="l33-·-平行结构与-not-only-but-also" tabindex="-1">L33 · 平行结构与 not only…but also <a class="header-anchor" href="#l33-·-平行结构与-not-only-but-also" aria-label="Permalink to &quot;L33 · 平行结构与 not only…but also {#l33-·-平行结构与-not-only-but-also}&quot;">​</a></h2><p>to question claims, comparing sources and explanations 不平行；应统一为三个动词短语。</p><p><strong>对照例句：</strong> The course teaches students to question claims, compare sources and explain their conclusions.</p><p>to 后三个动词 question、compare、explain 并列，共享不定式标记 to，宾语分别对应各动作。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">回看讲解和练习</a></p><h2 id="l34-·-倾向表达与概率范围" tabindex="-1">L34 · 倾向表达与概率范围 <a class="header-anchor" href="#l34-·-倾向表达与概率范围" aria-label="Permalink to &quot;L34 · 倾向表达与概率范围 {#l34-·-倾向表达与概率范围}&quot;">​</a></h2><p>tend to 不等于 always；不能将示例改写成“所有青少年都只向同伴求助”。</p><p><strong>对照例句：</strong> In this club, new members tend to ask their peers for help before approaching an adult.</p><p>In this club 限定范围；tend to ask 表倾向；before approaching 与主语 new members 共享执行者。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">回看讲解和练习</a></p><h2 id="l35-·-将来完成时与未来截止点" tabindex="-1">L35 · 将来完成时与未来截止点 <a class="header-anchor" href="#l35-·-将来完成时与未来截止点" aria-label="Permalink to &quot;L35 · 将来完成时与未来截止点 {#l35-·-将来完成时与未来截止点}&quot;">​</a></h2><p>by the time the crew will arrive 不用于普通未来时间从句；应使用 arrives。</p><p><strong>对照例句：</strong> By the time the simulated crew arrives, the support team will have checked every system.</p><p>arrives 为未来时间从句的一般现在时；will have checked 表该时点前完成。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">回看讲解和练习</a></p><h2 id="l36-·-倍数比较与百分比基数" tabindex="-1">L36 · 倍数比较与百分比基数 <a class="header-anchor" href="#l36-·-倍数比较与百分比基数" aria-label="Permalink to &quot;L36 · 倍数比较与百分比基数 {#l36-·-倍数比较与百分比基数}&quot;">​</a></h2><p>rose by 120 units 不等于 rose to 120 units；本例只增加20单位。</p><p><strong>对照例句：</strong> In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p><p>from…to… 给起点终点；an increase of 20% 为同位补充，基数是原来的100。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">回看讲解和练习</a></p><h2 id="l37-·-比较级重复与渐变表达" tabindex="-1">L37 · 比较级重复与渐变表达 <a class="header-anchor" href="#l37-·-比较级重复与渐变表达" aria-label="Permalink to &quot;L37 · 比较级重复与渐变表达 {#l37-·-比较级重复与渐变表达}&quot;">​</a></h2><p>more and more better 不成立；better 已是比较级，应写 better and better。</p><p><strong>对照例句：</strong> The records became more and more detailed over the course of the study.</p><p>more and more detailed 表渐变程度；over the course of… 限定变化发生的时间。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">回看讲解和练习</a></p><h2 id="l38-·-if、when-后的省略结构" tabindex="-1">L38 · if、when 后的省略结构 <a class="header-anchor" href="#l38-·-if、when-后的省略结构" aria-label="Permalink to &quot;L38 · if、when 后的省略结构 {#l38-·-if、when-后的省略结构}&quot;">​</a></h2><p>When travelling, the water… 容易把 travelling 的执行者错接成 water；应明确人作主语。</p><p><strong>对照例句：</strong> When travelling, check current local guidance rather than rely on an old account.</p><p>When travelling 相当于 when you are travelling；主句祈使句隐含主语 you，与分词执行者相同。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-038">回看讲解和练习</a></p><h2 id="l39-·-wish-后的时态与非现实意义" tabindex="-1">L39 · wish 后的时态与非现实意义 <a class="header-anchor" href="#l39-·-wish-后的时态与非现实意义" aria-label="Permalink to &quot;L39 · wish 后的时态与非现实意义 {#l39-·-wish-后的时态与非现实意义}&quot;">​</a></h2><p>不要把对现有稿件的遗憾写成 wish the opening is shorter；此处需要过去形式表达非现实。</p><p><strong>对照例句：</strong> I wish the opening were shorter, because the main point arrives too late.</p><p>wish 后 were shorter 表对当前文本的不满意；because 从句说明修改理由。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">回看讲解和练习</a></p><h2 id="l40-·-where-的地点与条件意义" tabindex="-1">L40 · where 的地点与条件意义 <a class="header-anchor" href="#l40-·-where-的地点与条件意义" aria-label="Permalink to &quot;L40 · where 的地点与条件意义 {#l40-·-where-的地点与条件意义}&quot;">​</a></h2><p>不要把“实验结束时”写成 where the experiment ends；普通时间关系应写 when the experiment ends。</p><p><strong>对照例句：</strong> Where the water meets the barrier, the pattern changes.</p><p>where 从句指地点；主句 the pattern changes 描述该区域的观察结果。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">回看讲解和练习</a></p><h2 id="l41-·-with-宾语-补足语" tabindex="-1">L41 · with + 宾语 + 补足语 <a class="header-anchor" href="#l41-·-with-宾语-补足语" aria-label="Permalink to &quot;L41 · with + 宾语 + 补足语 {#l41-·-with-宾语-补足语}&quot;">​</a></h2><p>with the observer stood… 不能把一般过去时直接放入该结构；此处应用 standing。</p><p><strong>对照例句：</strong> With the observer standing at a distance, the handler recorded the animal’s response.</p><p>observer 与 standing 是主动关系；with 短语交代背景，主句主语是 handler。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-041">回看讲解和练习</a></p><h2 id="l42-·-被动语态中的时态与体" tabindex="-1">L42 · 被动语态中的时态与体 <a class="header-anchor" href="#l42-·-被动语态中的时态与体" aria-label="Permalink to &quot;L42 · 被动语态中的时态与体 {#l42-·-被动语态中的时态与体}&quot;">​</a></h2><p>The signal has recorded 错把信号当记录者；应使用 has been recorded。</p><p><strong>对照例句：</strong> The signal has been recorded, but the data are still being analysed.</p><p>has been recorded 表已完成的记录；are being analysed 表正在进行的被动过程；data 在此按复数处理。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-042">回看讲解和练习</a></p><h2 id="l43-·-there-be-与存在命题" tabindex="-1">L43 · there be 与存在命题 <a class="header-anchor" href="#l43-·-there-be-与存在命题" aria-label="Permalink to &quot;L43 · there be 与存在命题 {#l43-·-there-be-与存在命题}&quot;">​</a></h2><p>There have a signal 不成立；应写 There is a signal 或 The receiver has detected a signal。</p><p><strong>对照例句：</strong> There may be a simpler explanation for the unusual signal.</p><p>there may be 为情态存在结构；a simpler explanation 是引入的新信息；for…限定解释对象。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-043">回看讲解和练习</a></p><h2 id="l44-·-限制性与非限制性从句的范围差异" tabindex="-1">L44 · 限制性与非限制性从句的范围差异 <a class="header-anchor" href="#l44-·-限制性与非限制性从句的范围差异" aria-label="Permalink to &quot;L44 · 限制性与非限制性从句的范围差异 {#l44-·-限制性与非限制性从句的范围差异}&quot;">​</a></h2><p>给 who 从句随意加逗号会改变范围：有逗号时通常将参加工作坊作为整组访客的补充信息。</p><p><strong>对照例句：</strong> The visitors who had attended the workshop recognised the greeting.</p><p>who…workshop 是限制性从句，只选出访客中的一部分；没有宣称全部访客参加过。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-044">回看讲解和练习</a></p><h2 id="l45-·-no-more-than-与-not-more-than" tabindex="-1">L45 · no more than 与 not more than <a class="header-anchor" href="#l45-·-no-more-than-与-not-more-than" aria-label="Permalink to &quot;L45 · no more than 与 not more than {#l45-·-no-more-than-与-not-more-than}&quot;">​</a></h2><p>not more than 10 表 ≤10，不是 &lt;10；上限本身也在允许范围内。</p><p><strong>对照例句：</strong> The summary contained no more than three pages, yet it raised questions the committee had overlooked.</p><p>no more than 强调篇幅很短；yet 连接篇幅与作用的反差；had overlooked 表忽略先于摘要提出问题。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-045">回看讲解和练习</a></p>',118)])])}const u=a(r,[["render",i]]);export{g as __pageData,u as default};
